True def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    patterns = [[9, 5, 3, 4], [2, 1, 3, 8], [4, 5, 6, 7]]
    lookup = {v: (pat, pat.index(v)) for pat in patterns for v in pat}
    for r, row in enumerate(grid):
        if sum(v != 0 for v in row) > 1:
            continue
        for c, v in enumerate(row):
            if v and v in lookup:
                pat, offset = lookup[v]
                start = c - offset
                for j, x in enumerate(pat):
                    cc = start + j
                    if 0 <= cc < w:
                        out[r][cc] = x
    return out
